<?php require 'config.php';$msg='';if(!isset($_SESSION['captcha']))$_SESSION['captcha']=(string)random_int(10,99);if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['captcha']??'')!==($_SESSION['captcha']??''))$msg='Wrong CAPTCHA.';else{try{$s=$pdo->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT)]);$msg='Registration successful. You can login now.';}catch(Exception $e){$msg='Email already registered or invalid details.';}}$_SESSION['captcha']=(string)random_int(10,99);} ?><h1>User Registration</h1><p><?=h($msg)?></p><form method="post"><input name="name" placeholder="Name" required><br><input type="email" name="email" placeholder="Email" required><br><input type="password" name="password" minlength="6" placeholder="Password (min 6 chars)" required><br><label>CAPTCHA: enter <?=h($_SESSION['captcha'])?> <input name="captcha" required></label><br><button>Register</button></form><a href="login.php">Login</a>